package com.vandorlabs.neoforge.canopy;

import net.minecraft.client.Minecraft;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;

/** Reordered/repeated real BE packet decoding, installed-client dispatch and visual replacement lifetime. */
final class CanopyMotionPacketClientChecks {
    private static final String REVISION="NativeCanopyMotionRevision";private static int checks;
    private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Canopy motion packets "+why);}
    private static CompoundTag tag(CompoundTag base,long sequence,boolean open,boolean waiting,float progress){var tag=base.copy();tag.putLong(REVISION,sequence);tag.putBoolean("Open",open);tag.putBoolean("CanopyWaitingForReservations",waiting);tag.putFloat("Progress",progress);return tag;}
    private static int deliver(Minecraft mc,NativeCanopyEntity owner,CompoundTag tag){return transfer(mc,owner,tag,true);}
    private static int transfer(Minecraft mc,NativeCanopyEntity owner,CompoundTag tag,boolean apply){var bytes=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),mc.level.registryAccess());try{var packet=ClientboundBlockEntityDataPacket.create(owner,(tile,registries)->tag.copy());ClientboundBlockEntityDataPacket.STREAM_CODEC.encode(bytes,packet);int count=bytes.readableBytes();var decoded=ClientboundBlockEntityDataPacket.STREAM_CODEC.decode(bytes);need(!bytes.isReadable()&&decoded.getTag().equals(tag),"actual packet round trip");if(apply)mc.getConnection().handleBlockEntityData(decoded);return count;}finally{bytes.release();}}
    private static double pose(Minecraft mc,NativeCanopyEntity owner,double time){var state=owner.publication();return NativeCanopyVisualClock.sample(mc.level,owner.getBlockPos(),owner.kind(),state.targetOpen(),state.waiting(),state.progress(),time);}
    static void run(Minecraft mc){var pos=CanopyEditorWorldFixture.root(0);var owner=(NativeCanopyEntity)mc.level.getBlockEntity(pos);need(owner!=null&&owner.available(),"installed complete client owner");var base=owner.getUpdateTag(mc.level.registryAccess());long sequence=base.getLong(REVISION)+10;NativeCanopyVisualClock.clear(mc.level);
        var open=tag(base,sequence,true,false,0);var legacy=open.copy();legacy.remove(REVISION);int legacyBytes=transfer(mc,owner,legacy,false);int modern=deliver(mc,owner,open);need(modern-legacyBytes==37,"publication revision adds exactly37 encoded bytes");need(owner.publication().targetOpen(),"fresh open accepted");need(pose(mc,owner,100)==0,"open starts at observed pose");need(pose(mc,owner,104)==.25,"sixteen-tick linear advance");
        var waiting=tag(base,sequence+1,false,true,1);deliver(mc,owner,waiting);need(owner.publication().waiting()&&pose(mc,owner,104)==1,"fresh blocked close captures held safe pose");deliver(mc,owner,waiting);need(pose(mc,owner,108)==1,"repeated waiting does not restart");
        var close=tag(base,sequence+2,false,false,1);deliver(mc,owner,close);need(pose(mc,owner,108)==1&&pose(mc,owner,110)==.875,"resume closing once");deliver(mc,owner,open);need(!owner.publication().targetOpen()&&!owner.publication().waiting(),"late old opposite-target packet rejected");var components=owner.components();var persistent=owner.getPersistentData().copy();var staleWaiting=waiting.copy();var changed=net.minecraft.core.component.DataComponentMap.builder().set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("stale-canopy-packet")).build();staleWaiting.put("components",net.minecraft.core.component.DataComponentMap.CODEC.encodeStart(mc.level.registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE),changed).getOrThrow());var stalePrivate=new CompoundTag();stalePrivate.putString("StaleCanopyPacket","must-not-install");staleWaiting.put("NeoForgeData",stalePrivate);deliver(mc,owner,staleWaiting);need(!owner.publication().waiting(),"late old waiting packet rejected");need(owner.components()==components&&owner.getPersistentData().equals(persistent),"stale guard precedes components and platform loading");need(pose(mc,owner,112)==.75,"late packets do not change motion");deliver(mc,owner,close);need(pose(mc,owner,114)==.625,"identical close packet does not recapture progress");
        var reverse=tag(base,sequence+3,true,false,.5F);deliver(mc,owner,reverse);need(owner.publication().targetOpen()&&pose(mc,owner,114)==.625,"new reversal preserves current visual pose");need(pose(mc,owner,116)==.75,"new reversal advances at same speed");
        var replacement=new NativeCanopyEntity(owner.getType(),pos,owner.getBlockState(),owner.kind());replacement.loadWithComponents(owner.getUpdateTag(mc.level.registryAccess()),mc.level.registryAccess());mc.level.setBlockEntity(replacement);need(pose(mc,replacement,116)==.75,"geometry/tile replacement preserves visual motion");deliver(mc,replacement,waiting);need(replacement.publication().targetOpen()&&!replacement.publication().waiting(),"replacement rejects stale state");
        // A real block removal has a different lifetime from a BE-only geometry replacement.
        var state=replacement.getBlockState();mc.level.setBlock(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);mc.level.setBlock(pos,state,3);var fresh=(NativeCanopyEntity)mc.level.getBlockEntity(pos);var reset=tag(base,0,false,false,0);fresh.loadWithComponents(reset,mc.level.registryAccess());need(pose(mc,fresh,116)==0,"genuine mining and same-kind placement retire old partial motion");var other=mc.level.getBlockState(CanopyEditorWorldFixture.root(4));mc.level.setBlock(pos,other,3);var different=(NativeCanopyEntity)mc.level.getBlockEntity(pos);var next=tag(base,0,true,false,.25F);next.putBoolean("CanopyOpenable",true);different.loadWithComponents(next,mc.level.registryAccess());need(!different.kind().equals(owner.kind())&&pose(mc,different,116)==.25,"different-kind placement starts its own observed pose");
        System.out.println("[vandorlabs][canopy-motion-packets] PASS checks="+checks+" packetBytesBefore="+legacyBytes+" packetBytesAfter="+modern+" actual decode/installed dispatch/reorder/repeat/wait/reversal/replacement/mining");
    }
}
